draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // table
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2-100, H/2-50, 200, 100);
  ctx.stroke();

  // mom
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2-120, H/2-80, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2-120, H/2-60);
  ctx.lineTo(W/2-120, H/2-40);
  ctx.lineTo(W/2-100, H/2-40);
  ctx.stroke();

  // dad
  ctx.beginPath();
  ctx.arc(W/2+120, H/2-80, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2+120, H/2-60);
  ctx.lineTo(W/2+120, H/2-40);
  ctx.lineTo(W/2+100, H/2-40);
  ctx.stroke();

  // kid1
  ctx.beginPath();
  ctx.arc(W/2-80, H/2-20+30*Math.sin(t), 15, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2-80, H/2-20+30*Math.sin(t)-15);
  ctx.lineTo(W/2-80, H/2-20+30*Math.sin(t));
  ctx.lineTo(W/2-60, H/2-20+30*Math.sin(t));
  ctx.stroke();

  // kid2
  ctx.beginPath();
  ctx.arc(W/2+80, H/2-20+30*Math.cos(t), 15, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2+80, H/2-20+30*Math.cos(t)-15);
  ctx.lineTo(W/2+80, H/2-20+30*Math.cos(t));
  ctx.lineTo(W/2+60, H/2-20+30*Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
